data.010-app-role.sh:
#!/bin/sh
set -eu
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" --set=app_password="$BAGAGE_APP_PASSWORD" <<'SQL'
CREATE ROLE bagage_app LOGIN PASSWORD :'app_password' NOSUPERUSER NOCREATEDB NOCREATEROLE;
SQL

data.permissions.sql:
-- Exécuter avec le propriétaire après les migrations. Rôle créé au préalable.
REVOKE ALL ON DATABASE bagage FROM PUBLIC;
GRANT CONNECT ON DATABASE bagage TO bagage_app;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO bagage_app;
GRANT SELECT ON roles TO bagage_app;
GRANT SELECT, INSERT, UPDATE ON users, vols, bagages TO bagage_app;
GRANT SELECT, INSERT ON historique_statuts TO bagage_app;
REVOKE UPDATE, DELETE, TRUNCATE ON historique_statuts FROM bagage_app;
-- L'API n'est ni propriétaire des tables ni superutilisateur.

data.default.conf:
server {
    listen 8080;
    server_name _;
    location = /healthz { access_log off; return 200 'ok'; }
    location / { return 308 https://localhost:15443$request_uri; }
}
server {
    listen 8443 ssl;
    server_name localhost 127.0.0.1;
    root /usr/share/nginx/html;
    server_tokens off;
    ssl_certificate /tls/public.crt;
    ssl_certificate_key /tls/public.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_tickets off;
    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options DENY always;
    add_header Referrer-Policy no-referrer always;
    add_header Cache-Control no-store always;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'" always;
    location ~ "^/api/track/[A-Fa-f0-9]{48}$" {
        limit_except GET { deny all; }
        proxy_pass http://api:8080;
        proxy_set_header Authorization "";
        proxy_set_header Host $host;
        proxy_connect_timeout 5s;
        proxy_read_timeout 15s;
        access_log off;
    }
    location /api { return 404; }
    location / { try_files $uri $uri/ /index.html; }
}

server {
    listen 127.0.0.1:8080;
    location = /healthz { access_log off; return 200 'ok'; }
    location / { return 404; }
}
server {
    # Le socket lui-même appartient à l'interface VPN, jamais à l'interface edge.
    listen 10.77.0.1:8443 ssl;
    server_name 10.77.0.1;
    root /usr/share/nginx/html;
    server_tokens off;
    ssl_certificate /tls/agents.crt;
    ssl_certificate_key /tls/agents.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_tickets off;
    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options DENY always;
    add_header Referrer-Policy no-referrer always;
    add_header Cache-Control no-store always;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'" always;
    client_max_body_size 64k;
    location /api/ {
        proxy_pass http://api:8080;
        proxy_set_header Host $host;
        proxy_connect_timeout 5s;
        proxy_read_timeout 15s;
        access_log off;
    }
    location / { try_files $uri $uri/ /index.html; }
}
